/* LXGW WenKai GB Regular v1.522 embedded (SIL OFL 1.1) - https://github.com/lxgw/LxgwWenKaiGB */
@font-face {
  font-family: "LXGW WenKai GB";
  src: url(data:font/woff2;base64,) format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

/* snow-day-glass: one whole-app wallpaper with small static glass surfaces.
   Scrolling and sidebar hover never animate a full-panel filter or shadow. */

:root[data-codexthemes-theme="snow-day-glass"] {
  --ct-canvas: #eef5fb;
  --ct-surface: rgba(255, 255, 255, 0.72);
  --ct-surface-strong: rgba(255, 255, 255, 0.86);
  --ct-raised: #ffffff;
  --ct-text: #2b3a49;
  --ct-muted: #5f7488;
  --ct-accent: #e0782d;
  --ct-accent-soft: rgba(224, 120, 45, 0.14);
  --ct-border: #c9dcea;
  --ct-focus: #3f9c5a;
  --ct-shadow: rgba(43, 58, 73, 0.14);
  --ct-art: url("./assets/artwork.jpg");

  /* Liquid-glass primitive tokens */
  --lg-tint: rgba(255, 255, 255, 0.38);
  --lg-tint-strong: rgba(255, 255, 255, 0.58);
  --lg-border: rgba(255, 255, 255, 0.55);
  --lg-highlight: rgba(255, 255, 255, 0.65);
  --lg-shadow: 0 3px 12px rgba(43, 58, 73, 0.09);
  --lg-blur: 6px;
  --lg-saturation: 108%;

  --ct-font-display: "Consolas", "LXGW WenKai GB", "Microsoft YaHei UI", sans-serif;
  --ct-font-body: "Consolas", "LXGW WenKai GB", "Microsoft YaHei UI", sans-serif;

  color-scheme: light;
  --color-background-surface: var(--ct-canvas) !important;
  --color-background-surface-under: var(--ct-surface) !important;
  --color-background-panel: var(--ct-surface-strong) !important;
  --color-background-control: var(--ct-raised) !important;
  --color-background-control-opaque: var(--ct-raised) !important;
  --color-background-editor-opaque: var(--ct-canvas) !important;
  --color-background-elevated-primary: var(--ct-raised) !important;
  --color-background-elevated-primary-opaque: var(--ct-raised) !important;
  --color-background-elevated-secondary: var(--ct-surface-strong) !important;
  --color-background-elevated-secondary-opaque: var(--ct-surface-strong) !important;
  --color-text-foreground: var(--ct-text) !important;
  --color-text-foreground-secondary: var(--ct-muted) !important;
  --color-text-foreground-tertiary: var(--ct-muted) !important;
  --color-icon-primary: var(--ct-text) !important;
  --color-icon-secondary: var(--ct-muted) !important;
  --color-icon-tertiary: var(--ct-muted) !important;
  --color-border: var(--ct-border) !important;
  --color-border-light: var(--ct-border) !important;
  --color-border-heavy: var(--ct-border) !important;
  --color-border-focus: var(--ct-focus) !important;
  --color-token-bg-primary: var(--ct-canvas) !important;
  --color-token-bg-secondary: var(--ct-surface) !important;
  --color-token-bg-tertiary: var(--ct-raised) !important;
  --color-token-main-surface-primary: transparent !important;
  --color-token-side-bar-background: rgba(255, 255, 255, 0.5) !important;
  --color-token-foreground: var(--ct-text) !important;
  --color-token-text-primary: var(--ct-text) !important;
  --color-token-text-secondary: var(--ct-muted) !important;
  --color-token-text-tertiary: var(--ct-muted) !important;
  --color-token-description-foreground: var(--ct-muted) !important;
  --color-token-icon-foreground: var(--ct-muted) !important;
  --color-token-input-background: var(--ct-raised) !important;
  --color-token-input-foreground: var(--ct-text) !important;
  --color-token-input-placeholder-foreground: var(--ct-muted) !important;
  --color-token-input-border: var(--ct-border) !important;
  --color-token-border: var(--ct-border) !important;
  --color-token-border-default: var(--ct-border) !important;
  --color-token-border-heavy: var(--ct-border) !important;
  --color-token-border-light: var(--ct-border) !important;
  --color-token-list-hover-background: rgba(255, 255, 255, 0.5) !important;
  --color-token-list-active-selection-background: var(--ct-accent-soft) !important;
  --color-token-list-active-selection-foreground: var(--ct-text) !important;
  --color-token-toolbar-hover-background: rgba(255, 255, 255, 0.5) !important;
  --color-token-button-background: var(--ct-accent) !important;
  --color-token-button-foreground: #ffffff !important;
  --color-token-button-border: var(--ct-border) !important;
  --color-token-link: #d96a1f !important;
  --color-token-text-link-foreground: #d96a1f !important;
  --color-token-text-link-active-foreground: #d96a1f !important;
  --color-token-primary: var(--ct-accent) !important;
  --color-token-focus-border: var(--ct-focus) !important;
  --color-token-dropdown-background: var(--ct-raised) !important;
  --color-token-dropdown-foreground: var(--ct-text) !important;
  --color-token-menu-background: var(--ct-raised) !important;
  --color-token-menu-border: var(--ct-border) !important;
  --color-token-checkbox-background: var(--ct-raised) !important;
  --color-token-checkbox-border: var(--ct-border) !important;
  --color-token-checkbox-foreground: var(--ct-accent) !important;
  --color-token-badge-background: var(--ct-accent-soft) !important;
  --color-token-badge-foreground: var(--ct-text) !important;
  --color-token-scrollbar-slider-background: rgba(95, 116, 136, 0.3) !important;
  --color-token-scrollbar-slider-hover-background: rgba(95, 116, 136, 0.45) !important;
  --color-token-scrollbar-slider-active-background: rgba(95, 116, 136, 0.55) !important;
  --color-token-conversation-header: var(--ct-muted) !important;
  --color-token-conversation-body: var(--ct-text) !important;
  --color-token-conversation-summary-leading: var(--ct-muted) !important;
  --color-token-conversation-summary-trailing: var(--ct-muted) !important;
  --color-token-non-assistant-body-descendant: var(--ct-muted) !important;
  --color-token-text-preformat-foreground: var(--ct-text) !important;
  --color-token-text-preformat-background: #f4f9fd !important;
  --color-token-text-code-block-background: #f4f9fd !important;
}

/* One static background for the entire window. Contain preserves the complete artwork. */
:root[data-codexthemes-theme="snow-day-glass"] body {
  color: var(--ct-text);
  font-family: var(--ct-font-body) !important;
  background: var(--ct-canvas) !important;
  isolation: isolate;
}

:root[data-codexthemes-theme="snow-day-glass"] body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  background: var(--ct-canvas) var(--ct-art) center / contain no-repeat;
  pointer-events: none;
}

:root[data-codexthemes-theme="snow-day-glass"] main.main-surface {
  color: var(--ct-text);
  background: transparent !important;
}

/* Scrolling the rail never resamples a rail-sized blur or animates its shadow. */
:root[data-codexthemes-theme="snow-day-glass"] aside.app-shell-left-panel {
  color: var(--ct-text);
  background: rgba(255, 255, 255, 0.5) !important;
  border-color: var(--lg-border);
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}

:root[data-codexthemes-theme="snow-day-glass"] aside.app-shell-left-panel a,
:root[data-codexthemes-theme="snow-day-glass"] aside.app-shell-left-panel button:not([aria-expanded]) {
  color: var(--ct-text);
  border-radius: 8px;
  transition: background-color 120ms ease, color 120ms ease;
}

:root[data-codexthemes-theme="snow-day-glass"] aside.app-shell-left-panel a:hover,
:root[data-codexthemes-theme="snow-day-glass"] aside.app-shell-left-panel button:not([aria-expanded]):hover {
  background: var(--lg-tint-strong);
  box-shadow: inset 0 1px 0 var(--lg-highlight), inset 0 0 0 1px rgba(255, 255, 255, 0.45);
}

:root[data-codexthemes-theme="snow-day-glass"] aside.app-shell-left-panel a[aria-current="page"],
:root[data-codexthemes-theme="snow-day-glass"] aside.app-shell-left-panel a[data-active="true"],
:root[data-codexthemes-theme="snow-day-glass"] aside.app-shell-left-panel button[aria-pressed="true"] {
  background: var(--lg-tint-strong);
  box-shadow: inset 0 1px 0 var(--lg-highlight), inset 0 0 0 1px var(--lg-border);
}

aside.app-shell-left-panel a:focus-visible,
aside.app-shell-left-panel button:focus-visible {
  outline: 2px solid var(--ct-focus);
  outline-offset: 1px;
}

/* Readability is local to bounded content, rather than a full-window veil. */
:root[data-codexthemes-theme="snow-day-glass"] [data-message-author-role],
:root[data-codexthemes-theme="snow-day-glass"] [data-codexthemes-surface="output"],
:root[data-codexthemes-theme="snow-day-glass"] [data-codexthemes-surface="diff"] {
  color: var(--ct-text);
  background: var(--ct-surface-strong);
  border-color: var(--ct-border);
}

:root[data-codexthemes-theme="snow-day-glass"] .composer-surface-chrome,
:root[data-codexthemes-theme="snow-day-glass"] [role="menu"],
:root[data-codexthemes-theme="snow-day-glass"] [role="dialog"] {
  color: var(--ct-text);
  background: var(--ct-surface-strong) !important;
  border-color: rgba(255, 255, 255, 0.9) !important;
  box-shadow: var(--lg-shadow), inset 0 1px 0 rgba(255, 255, 255, 0.9);
  -webkit-backdrop-filter: blur(var(--lg-blur)) saturate(var(--lg-saturation));
  backdrop-filter: blur(var(--lg-blur)) saturate(var(--lg-saturation));
}

main.main-surface[data-codexthemes-page="home"] h1 {
  font-family: var(--ct-font-display);
  letter-spacing: 0;
}

:root[data-codexthemes-theme="snow-day-glass"] .group\/home-suggestions button {
  color: var(--ct-text);
  background: rgba(255, 255, 255, 0.82);
  border-color: var(--lg-border);
  box-shadow: inset 0 1px 0 var(--lg-highlight);
  transition: background-color 120ms ease;
}

:root[data-codexthemes-theme="snow-day-glass"] .group\/home-suggestions button:hover {
  background: rgba(255, 255, 255, 0.92);
  box-shadow: inset 0 1px 0 var(--lg-highlight), inset 0 0 0 1px var(--lg-border);
}

main.main-surface[data-codexthemes-page="home"],
main.main-surface[data-codexthemes-page="conversation"],
aside.app-shell-left-panel {
  scrollbar-color: rgba(95, 116, 136, 0.35) transparent;
}

main.main-surface[data-codexthemes-page="home"] ::selection,
main.main-surface[data-codexthemes-page="conversation"] ::selection {
  background: rgba(63, 156, 90, 0.25);
}

[data-codex-terminal="true"] {
  --vscode-terminal-background: #f4f9fd !important;
  --vscode-terminal-foreground: var(--ct-text) !important;
  --color-background-panel: #f4f9fd !important;
  --color-background-editor-opaque: #f4f9fd !important;
  color: var(--ct-text) !important;
  background: #f4f9fd !important;
}

.xterm,
.xterm-viewport,
.xterm-screen,
[data-codexthemes-surface="terminal"] {
  color: var(--ct-text) !important;
  background: #f4f9fd !important;
}

:focus-visible { outline-color: var(--ct-focus); }

@media (max-width: 980px) {
  :root[data-codexthemes-theme="snow-day-glass"] { --lg-blur: 4px; }
}

@media (prefers-reduced-motion: reduce) {
  :root[data-codexthemes-theme="snow-day-glass"] aside.app-shell-left-panel a,
  :root[data-codexthemes-theme="snow-day-glass"] aside.app-shell-left-panel button:not([aria-expanded]) {
    transition: none !important;
  }
}

@supports not (backdrop-filter: blur(1px)) {
  :root[data-codexthemes-theme="snow-day-glass"] .composer-surface-chrome,
  :root[data-codexthemes-theme="snow-day-glass"] [role="menu"],
  :root[data-codexthemes-theme="snow-day-glass"] [role="dialog"] {
    background: #f8fbfd !important;
  }
}

@media (forced-colors: active) {
  :root[data-codexthemes-theme="snow-day-glass"] body { background: Canvas !important; }
  :root[data-codexthemes-theme="snow-day-glass"] aside.app-shell-left-panel,
  :root[data-codexthemes-theme="snow-day-glass"] .composer-surface-chrome,
  :root[data-codexthemes-theme="snow-day-glass"] [role="menu"],
  :root[data-codexthemes-theme="snow-day-glass"] [role="dialog"] {
    background: Canvas !important;
    color: CanvasText !important;
    box-shadow: none;
    backdrop-filter: none;
  }
}
